select is((select public.claim_free_choice_owner_approval('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',id,'inkendarapprovalevent','AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','2026-09-20T09:03:00Z')->>'kind' from approve_request),'BUSY','same approval retry respects active lease');
