select throws_ok($$insert into public.appointment(studio_id,tattoo_case_id,artist_profile_id,source,free_choice_request_id,status,confirmed_at,created_at) values('20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000082','50000000-0000-0000-0000-000000000001','BOOKING_OFFER',(select id from approve_request),'CONFIRMED','2026-09-21T13:05:00Z','2026-09-21T13:05:00Z')$$,'23514',null,'booking source cannot carry a free-choice request');
